std::vector<Point2d> intersections;
std::unordered_set<Point2d, std::hash<cg3::Point2d>> uniqueIntersections;

for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        CK_Segment_2 cgalSeg1(CK_Point_2(seg1.p1().x(), seg1.p1().y()),
                              CK_Point_2(seg1.p2().x(), seg1.p2().y()));
        CK_Segment_2 cgalSeg2(CK_Point_2(seg2.p1().x(), seg2.p1().y()),
                              CK_Point_2(seg2.p2().x(), seg2.p2().y()));

        auto result = intersection(cgalSeg1, cgalSeg2);
        if (result) {
            if (const CK_Point_2* ip = boost::get<CK_Point_2>(&*result)) {
                Point2d intersectionPoint(ip->x(), ip->y());
                if (uniqueIntersections.find(intersectionPoint) == uniqueIntersections.end()) {
                    uniqueIntersections.insert(intersectionPoint);
                    intersections.push_back(intersectionPoint);
                }
            }
            else if (const CK_Segment_2* is = boost::get<CK_Segment_2>(&*result)) {
                // Handle collinear segments - take both endpoints
                Point2d p1(is->source().x(), is->source().y());
                Point2d p2(is->target().x(), is->target().y());
                if (uniqueIntersections.find(p1) == uniqueIntersections.end()) {
                    uniqueIntersections.insert(p1);
                    intersections.push_back(p1);
                }
                if (uniqueIntersections.find(p2) == uniqueIntersections.end()) {
                    uniqueIntersections.insert(p2);
                    intersections.push_back(p2);
                }
            }
        }
    }
}

return intersections;

